effect.shader:
const float PI = 3.14159265;
const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

// O float que a textura de 8 bits devolve para o nível k (k/255 arredondado como o hardware), montado pelos bits: gravado
// num alvo de 8 bits volta a ser k em qualquer GPU (o `oitoBits` do Equilíbrio de cor).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

// A gaussiana de meio-lado `lado` (em pixels de `img`) no eixo `passo`, na mesma ordem de contas do Gaussian do AM (a
// do `am-gaussian-blur.xml`): os pesos tirados um do outro por multiplicação e duas amostras juntas numa leitura.
vec4 desfocar(sampler2D img, vec2 passo, vec2 st, float lado) {
    if (strength <= 0.0) return vec4(0.0);
    float sigma = lado / 2.14596602;
    highp vec3 g;
    g.x = 1.0 / (sqrt(2.0 * PI) * sigma);
    g.y = exp(-0.5 / (sigma * sigma));
    g.z = g.y * g.y;
    vec4 soma = vec4(0.0);
    highp float total = 0.0;
    soma += texture(img, st) * g.x;
    total += g.x;
    for (float i = 1.0; i <= lado; i += 2.0) {
        float d0 = i;
        float d1 = i + 1.0;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p0 = g.x;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p1 = g.x;
        float par = p0 + p1;
        float d = (d0 * p0 + d1 * p1) / par;
        vec2 stL = st - d * passo;
        vec2 stR = st + d * passo;
        soma += texture(img, stL) * par;
        soma += texture(img, stR) * par;
    }
    return soma / total;
}

// O meio-lado: Intensidade ÷ 2 × 1,14 ÷ 4 ÷ 3 da diagonal da imagem CHEIA (o `acPreviewSize` do AM).
float ladoDoDesfoque() {
    return strength / 2.0 * 1.14 / 4.0 / 3.0 * length(vec2(textureSize(pre, 0)));
}

// O fundo (a cena montada atrás da camada) no pixel da tela, pré-multiplicado (o do Anel).
vec3 fundoNoPixel() {
    ivec2 T = textureSize(comp, 0);
    ivec2 px = clamp(ivec2(floor(acTela(acScreenNorm) * vec2(T))), ivec2(0), T - 1);
    vec4 f = texelFetch(comp, px, 0);
    return f.rgb * f.a;
}

// A saída pré-multiplicada do AM (`q`, já em 8 bits) em cor reta; onde a cor passa do alfa, com o fundo (o `paraReta`
// do Anel e do Sharpen: o menor alfa que dá a mesma soma na composição Normal com qualquer opacidade).
vec4 paraReta(vec4 q) {
    if (all(lessThanEqual(q.rgb, vec3(q.a)))) return q.a > 0.0 ? vec4(q.rgb / q.a, q.a) : vec4(0.0);
    vec3 d = fundoNoPixel();
    vec3 sobra = q.rgb - d * q.a;
    vec3 folga = 1.0 - d;
    float a = q.a;
    for (int i = 0; i < 3; i++) {
        // Canal com o fundo cheio (1): lá e aqui a soma fica em 1 com qualquer alfa, então ele não pede nada.
        if (sobra[i] > 0.0 && folga[i] > 0.0) a = max(a, sobra[i] / folga[i]);
    }
    a = min(a, 1.0);
    return a > 0.0 ? vec4(clamp(d + sobra / a, 0.0, 1.0), a) : vec4(0.0);
}

void main() {
    if (acPass == 0) {
        // A camada do AM chega pré-multiplicada EM 8 BITS, pelo mais perto (o premul do Android); no opaco a cor já é o
        // float da textura, bit a bit.
        vec4 c = texture(inputImg, acScreenNorm);
        vec3 p = c.rgb;
        if (c.a < 1.0) {
            vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
            p = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
        }
        fragColor = vec4(p, c.a);
        return;
    }
    if (acPass == 1) {
        fragColor = texture(pre, acScreenNorm);
        return;
    }
    if (acPass == 2) {
        vec2 passo = vec2(1.0 / vec2(textureSize(downImg, 0)).x, 0.0);
        fragColor = desfocar(downImg, passo, acScreenNorm, ladoDoDesfoque());
        return;
    }
    if (acPass == 3) {
        // Na tela a entrada chega de pé (t = 0 embaixo, como no AM): o passo aponta para CIMA e a soma do par fica na
        // mesma ordem da dele (o de baixo primeiro). Deitada, o passo vira para baixo.
        float cima = acEntradaDePe == 1 ? 1.0 : -1.0;
        vec2 passo = vec2(0.0, cima / vec2(textureSize(blurH, 0)).y);
        vec4 r = desfocar(blurH, passo, acScreenNorm, ladoDoDesfoque());
        // Intensidade 0: o Gaussian do AM lê a própria camada aqui (na meia resolução: a média de 2 × 2).
        fragColor = strength <= 0.0 ? texture(pre, acScreenNorm) : r;
        return;
    }
    if (acPass == 4) {
        fragColor = texture(blurV, acScreenNorm);
        return;
    }
    if (acPass == 5) {
        // A conta do Unsharp do AM, na mesma ordem. O corte em 0..1 é o do alvo de 8 bits; escrito para o projeto de
        // 32 bits sair igual.
        vec4 blur = texture(hblur, acScreenNorm);
        vec4 base = texture(pre, acScreenNorm);
        float blurY = dot(blur.rgb, luminanceWeighting);
        float baseY = dot(base.rgb, luminanceWeighting);
        vec4 adjColor = base * (1.+amount) - (blur*amount);
        float t = smoothstep(threshold*0.75, (threshold+1.01)/2., abs(blurY-baseY)*4.);
        fragColor = clamp(showMask ? vec4(t,0.,0.,1.)*base.a : mix(base,adjColor,t), 0.0, 1.0);
        return;
    }

    fragColor = paraReta(texture(nitido, acScreenNorm));
}
